import re

def parse(path):
    steps = {}
    for line in open(path, encoding='utf-8', errors='replace'):
        m = re.match(r'.*step:(\d+) - (.*)', line)
        if not m:
            continue
        step = int(m.group(1))
        kv = {}
        for pair in m.group(2).split(' - '):
            if ':' in pair:
                k, _, v = pair.partition(':')
                try:
                    kv[k.strip()] = float(v.strip())
                except ValueError:
                    pass
        steps[step] = kv
    return steps

