import pyarrow.parquet as pq, re
def norm(s):
    return re.sub(r'[^a-z0-9]+', '', s.lower())
ev = pq.read_table('data/aime24-j9073.parquet').column('problem').to_pylist()
evn = {norm(p)[:120] for p in ev}
tr = pq.read_table('assets/skywork_or1_7b_math_difficulty1-15_16k.parquet')
print("train cols:", tr.column_names)
col = 'prompt' if 'prompt' in tr.column_names else tr.column_names[0]
trp = tr.column(col).to_pylist()
# prompt may be a list of messages
def totext(p):
    if isinstance(p, str): return p
    try:
        return " ".join(m.get('content','') if isinstance(m,dict) else str(m) for m in p)
    except Exception:
        return str(p)
trn = {norm(totext(p))[:120] for p in trp}
inter = evn & trn
print("train rows:", len(trn), "eval rows:", len(evn), "exact-prefix overlap:", len(inter))
EOF

